import{z as i,x as l,o as r,c as d,q as E,j as o,D as t,d as s,s as A,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"DMA 控制器与散布聚集","description":"","frontmatter":{"title":"DMA 控制器与散布聚集","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dma-scatter-gather.md","filePath":"cs/dma-scatter-gather.md","lastUpdated":1791063341000}'),p={name:"cs/dma-scatter-gather.md"};function m(D,a,M,C,c,P){const n=l("Mermaid");return r(),d("div",null,[a[2]||(a[2]=E('<h1 id="dma-控制器与散布聚集" tabindex="-1">DMA 控制器与散布聚集 <a class="header-anchor" href="#dma-控制器与散布聚集" aria-label="Permalink to &quot;DMA 控制器与散布聚集&quot;">​</a></h1><div class="epigraph"><p>设备当 PCIe 请求者自己发 Memory TLP，按描述符链表把不连续页搬成一次逻辑传输：CPU 不逐字拷，但要先把地址变成设备能懂的物理/IOVA。</p><footer>—— 据 PCI-SIG PCI Express Base Specification；Patterson and Hennessy, Computer Organization and Design (RISC-V)；Tanenbaum and Bos, Modern Operating Systems 整理</footer></div><p><a href="/cs/timers-tsc-hpet">上一课</a>与数据搬运无关。<a href="/cs/bus-mmio">MMIO</a> 点过设备当主设备。<a href="/cs/pcie-tlp-bar">PCIe 事务</a>允许端点发 Memory 读写。缺口是 <strong>DMA 与 scatter-gather</strong>：描述符、IOMMU、以及与 <a href="/cs/msi-msix">MSI</a> 的完成通知序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CPU <code>memcpy</code> 浪费缓存与核。DMA：软件在内存写描述符（源/目的/长度/下一项），门铃 BAR 踢设备，设备沿链表发 TLP。scatter-gather：用户缓冲跨很多物理页，描述符每页一项，设备串起来，不必拷成连续 bounce buffer（除非设备不能 SG 或不能 64 位地址）。缺口不是 TLP 类型，而是这条<strong>描述符协议</strong>与地址翻译。</p><p>IOMMU：设备看见 IOVA，硬件译成 PA，防止胡写。无 IOMMU 时驱动把 PA 直接填描述符，32 位设备需要 bounce。</p><p><span class="marginnote">直觉类比：scatter-gather 像从三个仓库给同一订单发货——描述符是三张提货单，写明哪个仓库、取多少、下一张单在哪，设备自己按单挨个取。没有 SG 就得先把货全搬进同一个大仓库（bounce buffer）再发车，白搬一趟。</span></p><h3 id="dma-不是「更快的-load-store-指令」" tabindex="-1">DMA 不是「更快的 load/store 指令」 <a class="header-anchor" href="#dma-不是「更快的-load-store-指令」" aria-label="Permalink to &quot;DMA 不是「更快的 load/store 指令」&quot;">​</a></h3><p>CPU 的 load 走缓存一致性；DMA 写主机内存必须让 CPU 看见（窥探或 IOMMU 一致性属性）。把 DMA 当 <code>rep movs</code> 的微码，缓存与围栏会漏。完成：设备写回状态再发 MSI；CPU 处理函数必须读到描述符写回，依赖 PCIe 与内存序——后课 fence 再从 ISA 侧收。</p><p><span class="marginnote">Patterson/Hennessy 与 Tanenbaum 有 DMA 教学。PCIe 规范定义请求者。Linux <code>dma_map_sg</code> 是软件接口，本课钉硬件合同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>准备：钉页、dma_map、填 SG 表。启动：写门铃。完成：MSI → 读状态、dma_unmap。错误：PCI AER、超时用<a href="/cs/timers-tsc-hpet">定时器</a>。与 NVMe：提交队列在内存，门铃是 BAR 写，设备 DMA 读命令、DMA 写数据。</p>',12)),(r(),o(B,null,{default:t(()=>[A(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CPU%5B%22%E9%92%89%E9%A1%B5%20%2B%20%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%20--%3E%20DB%5B%22%E9%97%A8%E9%93%83%20MMIO%22%5D%0A%20%20DB%20--%3E%20DEV%5B%22%E8%AE%BE%E5%A4%87%20DMA%20TLP%22%5D%0A%20%20DEV%20--%3E%20MEM%5B%22%E4%B8%BB%E6%9C%BA%E9%A1%B5%22%5D%0A%20%20DEV%20--%3E%20MSI%5B%22%E5%AE%8C%E6%88%90%E4%B8%AD%E6%96%AD%22%5D%0A%20%20MSI%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AUSB%20%E4%B9%9F%E6%98%AF%E6%8F%8F%E8%BF%B0%E7%AC%A6%20DMA%20%E7%9A%84%E7%89%B9%E4%BE%8B%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"教学片上 DMA 控制器（ARM PL330 一类）是独立主设备，协议同形，总线可能是 AXI 而不是 PCIe。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：32 位设备只能发出 0～4 GB 的地址；机器装 16 GB 内存时，落在 4 GB 以上的页它根本够不着，只能先把数据拷进 4 GB 以内的 bounce buffer。地址字段 64 位的设备没有这道墙，SG 才能真正省掉拷贝。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"下一课 USB 把事务组织成更复杂的层次，但高速设备仍 DMA。显示帧缓冲常 DMA 扫描出。固件启动早期可能无 IOMMU，驱动用恒等映射。本课把「块与包如何进内存」钉在 PCIe 之后。",-1)),(r(),o(B,null,{default:t(()=>[A(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20H%5B%22%E4%B8%80%E4%B8%AA%E7%BC%93%E5%86%B2%E6%95%A3%E5%9C%A8%203%20%E4%B8%AA%E4%B8%8D%E8%BF%9E%E7%BB%AD%E7%89%A9%E7%90%86%E9%A1%B5%22%5D%20--%3E%20D0%5B%22%E6%8F%8F%E8%BF%B0%E7%AC%A6%200%EF%BC%9A%E9%A1%B5%20A%EF%BC%8C4%20KB%22%5D%0A%20%20D0%20--%3E%7C%22next%22%7C%20D1%5B%22%E6%8F%8F%E8%BF%B0%E7%AC%A6%201%EF%BC%9A%E9%A1%B5%20F%EF%BC%8C4%20KB%22%5D%0A%20%20D1%20--%3E%7C%22next%22%7C%20D2%5B%22%E6%8F%8F%E8%BF%B0%E7%AC%A6%202%EF%BC%9A%E9%A1%B5%20C%EF%BC%8C1%20KB%22%5D%0A%20%20D2%20--%3E%20E%5B%22%E6%9C%AB%E9%A1%B9%E6%A0%87%E8%AE%B0%E7%BB%93%E6%9D%9F%22%5D%0A%20%20DEV%5B%22%E8%AE%BE%E5%A4%87%E6%8C%89%E9%93%BE%E9%80%90%E9%A1%B5%20DMA%EF%BC%8C%E4%B8%8D%E6%8B%B7%E8%B4%9D%22%5D%20-.-%3E%20D0%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p><span class="marginnote">常见误区：以为 MSI 中断一到就能随便读数据。中断只说明「设备声称写完了」，CPU 侧还要保证状态写回对核可见、必要时作废缓存并按内存序读。顺序反了或少了 fence，读到旧值的责任在驱动，不在硬件。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 IOMMU 页表格式（后课 Sv39 是 CPU 侧；IOMMU 另规格）。不把 RDMA 网卡动词表抄来。不进入 GPU 显存 pinning 的全部 API。</p><p>后课默认：DMA 是设备发起的内存 TLP，SG 描述符描述非连续页；完成靠写回+MSI。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CPU 准备描述符与门铃；设备搬数据。</li><li>scatter-gather 避免 bounce；IOMMU 翻译 IOVA。</li><li>可见性与中断序是正确性一部分。</li><li>出处：PCI-SIG；Patterson and Hennessy, COD；Tanenbaum and Bos。</li></ul>',6))])}const I=i(p,[["render",m]]);export{u as __pageData,I as default};
